use verus::prelude::*;

//=== is_close_i8 ===
//
// Pure function that checks whether |a - b| < tol, without overflow.
#[requires(tol as int >= 0)] 
#[ensures(result <==> ((a as int - b as int).abs() < (tol as int)))]
fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Compute difference in a wider type to avoid overflow, then take absolute value.
    let diff = (a as i16 - b as i16).abs();
    diff < tol as i16
}

//=== np_isclose ===
//
// Elementwise version of NumPy’s “isclose” for i8 vectors.
#[requires(a.len() == b.len())]
#[requires(tol as int > 0)] 
#[ensures(result.len() == a.len())]
#[ensures(forall(|i: usize| i < a.len() ==> result[i] == is_close_i8(a[i], b[i], tol)))]
fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Runtime sanity checks (these match our specs)
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");
    assert!(tol > 0, "Tolerance must be strictly positive");

    a.iter()
     .zip(b.iter())
     .map(|(&x, &y)| is_close_i8(x, y, tol))
     .collect()
}

